struct Offset { int delta; int apply(int x) const { return x+delta; } };
struct Limit { int high; int apply(int x) const { return x>high ? high : x; } };
class Pipeline { Offset offset_; Limit limit_; public: Pipeline(int delta,int high) : offset_{delta}, limit_{high} {} int run(int x) const { return limit_.apply(offset_.apply(x)); } };
int solve(int a,int b) { return Pipeline{b,100}.run(a); }

